void rsr_feature_err_add ( Rsr_Feature_Err_Code code )
{  
	UInt8 ptr = rsr_feature_err.count % RS_FEAT_ERR_BUFF_SIZE ;
 
	rsr_feature_err.code[ptr] = code ;
	rsr_feature_err.count++ ;
	rsr_feature_err_save();
}



